{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {node['id']: node for node in nodes}
    parent_children = {}
    for node in nodes:
        parent = node.get('parent')
        if parent is not None:
            parent_children.setdefault(parent, []).append(node['id'])
    retained = set(node_map.keys())
    # Verify each required symbol exists
    symbol_present = {sym: False for sym in required_symbols}
    for node in nodes:
        if node['symbol'] in symbol_present:
            symbol_present[node['symbol']] = True
    if not all(symbol_present.values()):
        raise ValueError('Required symbols not present in tree.')
    # Sort by depth descending, then node id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if node['parent'] is None:
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        children = parent_children.get(nid, [])
        if any(child in retained for child in children):
            continue
        # Tentative removal
        temp_retained = retained - {nid}
        req_covered = set()
        for rid in temp_retained:
            if node_map[rid]['symbol'] in required_symbols:
                req_covered.add(node_map[rid]['symbol'])
        if req_covered == set(required_symbols):
            retained = temp_retained
            removed.append(nid)
    retained_ids = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_ids}
"}
